import StatisticsCards from "@/components/cards/StatisticsCards";
import UnderlineHeading from "@/components/heading/UnderlineHeading";
import GroupIcon from "@/components/icons/user/GroupIcon";
import MinusUserIcon from "@/components/icons/user/MinusUserIcon";
import TwoUsersIcon from "@/components/icons/user/TwoUsersIcon";
import UserRemoveIcon from "@/components/icons/UserRemoveIcon";
import { endpoints } from "@/lib/axios/axios-global";
import { Card } from "@/types/statistics";
import { useEffect } from "react";
import { apiGet } from "@/lib/axios/axios-utils";
import { traineesStats } from "../types/configs.types";
import { useState } from "react";
import TraineesList from "../components/traineesList/TraineesList";

const Trainees = () => {
    const [stats, setStats] = useState<traineesStats | null>(null);

    useEffect(() => {
        const fetchStats = async () => {
            try {
                const res = await apiGet({ endpoint: endpoints.employee.dashboard });
                setStats(res.data.data);
            } catch (err) {
                setStats(null);
            }
        };
        fetchStats();
    }, []);

    const cards: Card[] = [
        { text: 'إجمالي المتدربين', num: stats?.total_trainees, percent: 12, icon: <GroupIcon /> },
        { text: 'متوسط التقيم', num: stats?.average_completion_rate, percent: -0.3, icon: <TwoUsersIcon /> },
        { text: 'معدل الاكمال', num: stats?.total_completed, percent: 0, icon: <UserRemoveIcon /> },
        { text: 'معدل الحضور', num: stats?.attendance_rate, percent: -0.3, icon: <MinusUserIcon /> },
    ];

    return <div className="w-full mt-6">
        <UnderlineHeading text="المتدربين" />
        <StatisticsCards cards={cards} className="my-6"/>
        <TraineesList />
    </div>;
};

export default Trainees;
